package org.kanger;
import java.util.*;
import org.kanger.ContextProductionNativeBinding.*;

/** A shared cut must retain whole member identities and reject hidden physical aliases. */
public final class ContextTrustedCutScopeRunner {
    static int checks;
    static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
    interface Action{void run()throws Exception;}
    static void reject(Action a,String why)throws Exception{boolean seen=false;try{a.run();}catch(IllegalArgumentException|IllegalStateException e){seen=true;}require(seen,why);}
    static Snapshot bind(long id,boolean local,String text)throws Exception{User u=new User();Mind m=new Mind(u);u.setCurrentMind(m);require(m.compile(text,null,false),"native scope fixture");ContextProductionInventory i=ContextProductionInventory.inspect(m,new UUID(0,id),1,local,Collections.emptyList(),1000);Result r=ContextProductionNativeBinding.bind(m,i,64000000,500000);require(r.bound,"whole native member bound: "+r.reason);return r.snapshot;}
    public static void main(String[] args){try{
        System.setProperty("user.home",java.nio.file.Files.createTempDirectory("trusted-cut-scope-").toString());Snapshot x=bind(1,true,"!anchor(1);"),a=bind(2,false,"!p(1);"),b=bind(3,false,"!p(1);"),c=bind(4,false,"!other(1);");List<Snapshot> mutable=new ArrayList<>(Arrays.asList(a,b));Snapshot group=ContextProductionNativeBinding.trusted("own",mutable,64000000);mutable.clear();
        require(group.members.equals(Arrays.asList(a,b))&&group.primary.size()==2&&group.primary.get(0)==a.primary.get(0)&&group.primary.get(1)==b.primary.get(0),"sealed group retains exact member/whole Entry objects despite caller list mutation");require(a.primary.get(0).source.rule==b.primary.get(0).source.rule&&!a.primary.get(0).source.equals(b.primary.get(0).source),"same native rule ID and identical assertion in different members retain distinct Sources");
        for(Snapshot cut:Arrays.asList(group,ContextProductionNativeBinding.trusted("own",Arrays.asList(b,a),64000000))){ContextUniversalFamilyInspection.Result r=ContextUniversalFamilyInspection.inspect(x,Arrays.asList(cut),16,16,16,65536,1000000,64000000);require(r.status==ContextUniversalFamilyInspection.Status.CONSISTENT&&r.certificate.cuts.size()==2,"one shared logical cut plus X");require(ContextUniversalFamilyAudit.audit(r,x,Arrays.asList(cut),16,65536,64000000).verified,"exact member-aware model audit");require(r.certificate.input.products.isEmpty(),"private shared facts do not become communal X products");}
        Snapshot whole=bind(5,false,"!left(1)&&right(1);"),compound=ContextProductionNativeBinding.trusted("compound",Arrays.asList(a,whole),64000000);require(compound.primary.size()==2&&compound.primary.get(1)==whole.primary.get(0)&&whole.primary.get(0).clauses.size()==2,"whole compound member remains one Source with both clauses");
        Snapshot cacheA=bind(6,false,"!@x a(x)->b(x); !a(1);"),cacheB=bind(7,false,"!@x a(x)->b(x); !a(1);"),cached=ContextProductionNativeBinding.trusted("cached",Arrays.asList(cacheA,cacheB),64000000);require(!cacheA.excludedGenerated.isEmpty()&&cacheA.excludedGenerated.equals(cacheB.excludedGenerated)&&cached.excludedGeneratedByContext.size()==2&&cached.excludedGeneratedByContext.get(cacheA.inventory.context).equals(cacheA.excludedGenerated)&&cached.excludedGeneratedByContext.get(cacheB.inventory.context).equals(cacheB.excludedGenerated),"same generated native IDs remain excluded and accounted separately for both member contexts");require(cached.primary.size()==4,"member-generated conclusions never become group primaries");
        reject(()->ContextProductionNativeBinding.trusted("own",Arrays.asList(a,a),64000000),"duplicate member rejected");reject(()->ContextProductionNativeBinding.trusted("nested",Arrays.asList(group),64000000),"nested compound cut rejected");reject(()->ContextProductionNativeBinding.trusted("own",Arrays.asList(x),64000000),"local X cannot be foreign trusted member");reject(()->ContextProductionNativeBinding.trusted("bad name",Arrays.asList(a),64000000),"invalid group metadata refused");reject(()->ContextProductionNativeBinding.trusted("own",Arrays.asList(a,b),1),"bounded grouping work stop");
        ContextUniversalCandidate.Evaluation staged=ContextUniversalCandidate.qualify(x,Arrays.asList(group),"!safe(1);",1000,16,16,16,65536,1000000,64000000,500000,64000000);require(staged.status==ContextUniversalFamilyInspection.Status.CONSISTENT,"detached candidate retains grouped foreign inventories");require(ContextUniversalCandidateAudit.audit(staged,x,Arrays.asList(group),"!safe(1);",16,65536,64000000).verified,"candidate audit checks exact original grouped physical members");require(!ContextProductionCandidate.stage(x,Arrays.asList(group),"!safe(1);",2,64000000,500000).prepared,"candidate row bound counts all group members, not only first routing member");
        Snapshot aliasX=bind(1,false,"!other(1);"),hidden=ContextProductionNativeBinding.trusted("hidden",Arrays.asList(c,aliasX),64000000);ContextUniversalFamilyInspection.Result bad=ContextUniversalFamilyInspection.inspect(x,Arrays.asList(hidden),16,16,16,65536,1000000,64000000);require(bad.status==ContextUniversalFamilyInspection.Status.INCOMPLETE&&bad.reason.contains("Repeated physical"),"X alias hidden in non-routing member rejected");
        Snapshot overlap=ContextProductionNativeBinding.trusted("second",Arrays.asList(c,b),64000000);bad=ContextUniversalFamilyInspection.inspect(x,Arrays.asList(group,overlap),16,16,16,65536,1000000,64000000);require(bad.status==ContextUniversalFamilyInspection.Status.INCOMPLETE&&bad.reason.contains("Repeated physical"),"physical member repeated across two distinct routing cuts rejected");
        require(!ContextProductionFamilyAssembly.assemble(x,Arrays.asList(group),64000000).assembled,"witness replay path does not silently treat routing member as whole group");
        System.out.println("CONTEXT_TRUSTED_CUT_SCOPE_PASS checks="+checks);System.exit(0);
    }catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
